  const levels = Object.freeze(sorted.map((level, index) => Object.freeze({
    ...level, number: index + 1, twist: window.MuseumTwists ? window.MuseumTwists.forIndex(index) : null,
    reward: Math.round((120 + index * 15) * (window.MuseumTwists && window.MuseumTwists.forIndex(index) ? 1.2 : 1)),
    prologue: Object.freeze((level.prologue || []).map(Object.freeze))
  })));
  const byId = new Map(levels.map(level => [level.id, level]));
  window.MuseumLevels = Object.freeze({
    all() { return levels; },
    get(id) { return byId.get(id) || levels[0]; },
    at(index) { return levels[Math.max(0, Math.min(levels.length - 1, index | 0))]; },
    indexOf(id) { return Math.max(0, levels.findIndex(level => level.id === id)); },
    next(id) { const index = levels.findIndex(level => level.id === id); return index >= 0 && index + 1 < levels.length ? levels[index + 1] : null; },
    first() { return levels[0]; },
    count: levels.length
  });
